import csv, json
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime, date, time, timedelta

INPUT = "/app/input"
ORDER_DATE = date(2026, 9, 25)

try:
    from zoneinfo import ZoneInfo
    ORDER_PLACED = datetime(2026, 9, 25, 14, 40, tzinfo=ZoneInfo("America/Chicago"))
    def store_order_local(tz):
        return ORDER_PLACED.astimezone(ZoneInfo(tz)).replace(tzinfo=None)
except Exception:
    def store_order_local(tz):
        if tz == "America/New_York":
            return datetime(2026, 9, 25, 15, 40)
        return datetime(2026, 9, 25, 14, 40)

# Catalogue
catalog = {}
with open(f"{INPUT}/cord_catalogue.csv", newline="") as f:
    for row in csv.DictReader(f):
        row = {k: v.strip() for k, v in row.items()}
        catalog[row["sku"]] = row

sku_aliases = {}
for sku, row in catalog.items():
    sku_aliases[sku.upper()] = {row["sku"].upper(), row["supplier_part"].upper()}

# Offers, deduplicated by offer_id
offers = []
seen = set()
with open(f"{INPUT}/same_day_offers.csv", newline="") as f:
    for row in csv.DictReader(f):
        row = {k: v.strip() for k, v in row.items()}
        oid = row["offer_id"]
        if oid in seen:
            continue
        seen.add(oid)
        offers.append(row)

# Store directory, effective row only
store_rows = {}
with open(f"{INPUT}/store_directory.csv", newline="") as f:
    for row in csv.DictReader(f):
        row = {k: v.strip() for k, v in row.items()}
        sid = row["store_id"].upper()
        row["eff_date"] = date.fromisoformat(row["effective_from"])
        row["distance_mi"] = Decimal(row["distance_mi"])
        row["sales_tax_pct"] = Decimal(row["sales_tax_pct"])
        row["same_day_suspended"] = row["same_day_suspended"].upper() == "Y"
        store_rows.setdefault(sid, []).append(row)

stores = {}
for sid, rows in store_rows.items():
    eff = [r for r in rows if r["eff_date"] <= ORDER_DATE]
    stores[sid] = max(eff, key=lambda r: r["eff_date"])

# Tax jurisdictions
tax_rates = {}
with open(f"{INPUT}/tax_jurisdictions.csv", newline="") as f:
    for row in csv.DictReader(f):
        row = {k: v.strip() for k, v in row.items()}
        tax_rates[(row["city"].upper(), row["state"].upper())] = Decimal(row["combined_sales_tax_pct"])

DELIVERY_TAX = tax_rates[("PHENIX CITY", "AL")]
DELIVERY_FEE = Decimal("9.99")

# Notices parsed manually from store_notices.md for this fixed input
cutoff_overrides = {
    ("ST-08", "PICKUP"): time(16, 0),
}
paused_methods = {
    ("ST-52", "DELIVERY"): True,
}

# Stock ledger
ledger = []
with open(f"{INPUT}/stock_ledger.csv", newline="") as f:
    for row in csv.DictReader(f):
        row = {k: v.strip() for k, v in row.items()}
        row["store_id"] = row["store_id"].upper()
        row["item_code"] = row["item_code"].upper()
        row["posted_local"] = datetime.fromisoformat(row["posted_local"])
        row["qty"] = int(row["qty"])
        row["event"] = row["event"].upper()
        ledger.append(row)

def effective_stock(store_id, sku):
    store_id = store_id.upper()
    aliases = sku_aliases[sku.upper()]
    opening_qty = None
    opening_dt = None
    lines = []
    for r in ledger:
        if r["store_id"] != store_id or r["item_code"] not in aliases:
            continue
        if r["event"] == "OPENING" and r["posted_local"].date() == ORDER_DATE:
            if opening_qty is None or r["posted_local"] > opening_dt:
                opening_qty = r["qty"]
                opening_dt = r["posted_local"]
        else:
            lines.append(r)
    if opening_qty is None:
        opening_qty = 0
        opening_dt = datetime.combine(ORDER_DATE, time(0, 0))

    stock = opening_qty
    order_local = store_order_local(stores[store_id]["timezone"])
    for r in lines:
        if r["posted_local"] <= opening_dt:
            continue
        if r["posted_local"] > order_local:
            continue
        if r["event"] in ("OPENING", "RECEIPT", "VOID"):
            stock += r["qty"]
        elif r["event"] in ("SALE", "HOLD", "TRANSFER_OUT"):
            stock -= r["qty"]
    return stock

def parse_length_ft(s):
    s = s.strip()
    if s.endswith("ft"):
        return Decimal(s[:-2].strip())
    if s.endswith("m"):
        return Decimal(s[:-1].strip()) / Decimal("0.3048")
    raise ValueError(f"unparsed length {s}")

def fit_reason(row):
    if row["connector"].upper() != "C7":
        return "FIT_CONNECTOR"
    if row["polarized"].upper() != "N":
        return "FIT_POLARIZED"
    length_ft = parse_length_ft(row["length"])
    awg = int(row["conductor_awg"])
    if length_ft <= Decimal("6"):
        gauge_ok = True
    elif length_ft <= Decimal("15"):
        gauge_ok = awg <= 18
    else:
        gauge_ok = awg <= 16
    if not gauge_ok:
        return "FIT_GAUGE"
    if length_ft < Decimal("10") or length_ft > Decimal("15"):
        return "FIT_LENGTH"
    return None

def round_cent(d):
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

def landed_cost(offer, cat_row):
    price = Decimal(cat_row["price_usd"])
    if offer["method"] == "DELIVERY":
        rate = DELIVERY_TAX
        fee = DELIVERY_FEE
    else:
        rate = stores[offer["store_id"].upper()]["sales_tax_pct"]
        fee = Decimal("0.00")
    base = price + price * rate / Decimal("100")
    return round_cent(round_cent(base) + fee)

rows_out = []
eligible = []

for offer in offers:
    oid = offer["offer_id"]
    sid = offer["store_id"].upper()
    sku = offer["sku"]
    method = offer["method"].upper()
    cat = catalog[sku]
    reason = fit_reason(cat)
    stock = None
    if reason is None:
        stock = effective_stock(sid, sku)
        if stock < 1:
            reason = "NO_STOCK"
        elif method == "DELIVERY" and stock < 2:
            reason = "STOCK_RESERVE"
        elif stores[sid]["same_day_suspended"] or paused_methods.get((sid, method), False):
            reason = "SAME_DAY_SUSPENDED"
        else:
            order_local = store_order_local(stores[sid]["timezone"])
            cutoff = cutoff_overrides.get((sid, method), time(15, 0))
            if order_local.time() >= cutoff:
                reason = "CUTOFF_PASSED"
            elif method == "DELIVERY" and stores[sid]["distance_mi"] > Decimal("10"):
                reason = "OUT_OF_RADIUS"
            else:
                reason = "NONE"

    if reason == "NONE":
        decision = "ELIGIBLE"
        landed = landed_cost(offer, cat)
        order_local = store_order_local(stores[sid]["timezone"])
        ready = order_local + timedelta(hours=2) if method == "PICKUP" else datetime(2026, 9, 25, 20, 0)
        eligible.append({
            "offer_id": oid,
            "landed": landed,
            "ready": ready,
            "distance": stores[sid]["distance_mi"],
        })
    else:
        decision = "INELIGIBLE"
        landed = ""

    rows_out.append({
        "offer_id": oid,
        "decision": decision,
        "reason_code": reason,
        "landed_cost_usd": landed if decision == "ELIGIBLE" else "",
    })
    print(f"{oid}: {decision} {reason} landed={landed} stock={stock} store={sid} sku={sku} method={method}")

rows_out.sort(key=lambda r: r["offer_id"])

with open("/app/offer_evaluation.csv", "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=["offer_id", "decision", "reason_code", "landed_cost_usd"], lineterminator="\n")
    writer.writeheader()
    for r in rows_out:
        writer.writerow({
            "offer_id": r["offer_id"],
            "decision": r["decision"],
            "reason_code": r["reason_code"],
            "landed_cost_usd": str(r["landed_cost_usd"]) if r["decision"] == "ELIGIBLE" else "",
        })

chosen = min(eligible, key=lambda e: (e["landed"], e["ready"], e["distance"], e["offer_id"]))
results = {
    "eligible_offer_count": len(eligible),
    "chosen_offer_id": chosen["offer_id"],
    "chosen_total_usd": float(chosen["landed"]),
}

with open("/app/results.json", "w") as f:
    json.dump(results, f, indent=2)
    f.write("\n")

print("\nWROTE:")
print(json.dumps(results, indent=2))
PY
